using System;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using Grasshopper.Kernel;
using Grasshopper.Kernel.Types;
using Rhino;
using Rhino.Geometry;
namespace PlugInSolar {
public sealed class PvExposureMapComponent:GH_Component {
 public PvExposureMapComponent():base("PV Exposure Map","Exposure Map","Visualize retained grid-cell irradiation from PV Solar Exposure. Independent legend limits allow fair layout comparisons; no solar calculation is repeated.","Plug-In Solar","04 Visualization"){}
 public override Guid ComponentGuid=>new Guid("1d98fa40-7f70-47da-a892-f70ed79c2403");protected override Bitmap Icon=>Assets.Icon("irradiance");
 protected override void RegisterInputParams(GH_InputParamManager p){p.AddGenericParameter("Solar Exposure Results","Results","PV Solar Exposure → Results. Must contain retained grid-cell irradiation and vertices.",GH_ParamAccess.item);int a=p.AddNumberParameter("Legend Minimum","Min","Optional fixed minimum in kWh/m². Pair with Maximum to compare alternatives using one scale.",GH_ParamAccess.item);p[a].Optional=true;int b=p.AddNumberParameter("Legend Maximum","Max","Optional fixed maximum in kWh/m². Default uses all analysis cells, not panel averages.",GH_ParamAccess.item);p[b].Optional=true;int c=p.AddPlaneParameter("Legend Plane","Plane","Optional location and orientation for the legend. Default places it beside the analysis geometry.",GH_ParamAccess.item);p[c].Optional=true;}
 protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddMeshParameter("Exposure Map","Map","Panel mesh with one color per analysis cell. Blue = lower, red = higher period irradiation. Units kWh/m².",GH_ParamAccess.list);p.AddGeometryParameter("Legend","Legend","Color bar, numeric ticks, units and supplied-period label. Default size follows the analysis geometry.",GH_ParamAccess.list);p.AddNumberParameter("Cell Irradiation","Cell H","kWh/m², branch {panel index}, in cell/mesh-face order. Connect to a custom spatial heatmap with Analysis Mesh.",GH_ParamAccess.tree);p.AddMeshParameter("Analysis Mesh","Mesh","Uncolored analysis cells corresponding exactly to Cell Irradiation values.",GH_ParamAccess.list);p.AddNumberParameter("Chart Values","Values","Panel-average period irradiation, kWh/m²; connect with Chart Labels to bar charts.",GH_ParamAccess.list);p.AddTextParameter("Chart Labels","Labels","Panel IDs aligned with Chart Values.",GH_ParamAccess.list);p.AddTextParameter("Summary Data","Summary","CSV rows: panel ID, area m², irradiation kWh/m², incident solar kWh, irradiation reduction %. Not electricity.",GH_ParamAccess.list);p.AddTextParameter("Report","Report","Legend limits, time period and interpretation. Time indexing remains inside grouped Results.",GH_ParamAccess.item);}
 public static Mesh PanelMesh(PvExposureResult r,int i,bool colored,double min,double max){var m=new Mesh();for(int j=0;j<r.CellVertices[i].Length;j++){var v=r.CellVertices[i][j];int k=m.Vertices.Count;for(int z=0;z<4;z++)m.Vertices.Add(v[z*3],v[z*3+1],v[z*3+2]);m.Faces.AddFace(k,k+1,k+2,k+3);if(colored){var c=Ramp((r.CellIrradiation[i][j]-min)/(max-min));for(int z=0;z<4;z++)m.VertexColors.Add(c);}}m.Normals.ComputeNormals();return m;}
 public static Color Ramp(double q){q=Math.Max(0,Math.Min(1,q));var colors=new[]{Color.FromArgb(45,70,200),Color.FromArgb(60,175,235),Color.FromArgb(255,245,160),Color.FromArgb(250,140,35),Color.FromArgb(200,35,30)};double p=q*4;int i=Math.Min(3,(int)p);double x=p-i;return Color.FromArgb((int)(colors[i].R*(1-x)+colors[i+1].R*x),(int)(colors[i].G*(1-x)+colors[i+1].G*x),(int)(colors[i].B*(1-x)+colors[i+1].B*x));}
 protected override void SolveInstance(IGH_DataAccess da){try{IGH_Goo data=null;if(!da.GetData(0,ref data))return;var r=PvPanelCatalog.Unwrap<PvExposureData>(data).Data;if(r.CellIrradiation==null||r.CellVertices==null)throw new ArgumentException("These legacy results have no grid cells. Recalculate using the upgraded PV Solar Exposure.");var values=r.CellIrradiation.SelectMany(x=>x).ToArray();double min=values.Min(),max=values.Max();bool fixedMin=da.GetData(1,ref min),fixedMax=da.GetData(2,ref max);PvSeries.Check(min,"Legend minimum");PvSeries.Check(max,"Legend maximum");if(max<min||(max==min&&(fixedMin||fixedMax)))throw new ArgumentException("Legend Maximum must exceed Minimum.");if(max==min){double d=Math.Max(.01,Math.Abs(min)*.05);min-=d;max+=d;}
 var colored=new List<Mesh>();var raw=new List<Mesh>();var bounds=BoundingBox.Empty;for(int i=0;i<r.Ids.Length;i++){colored.Add(PanelMesh(r,i,true,min,max));raw.Add(PanelMesh(r,i,false,min,max));bounds.Union(raw[i].GetBoundingBox(true));}double size=Math.Max(bounds.Diagonal.Length*.12,1e-3);Plane plane=new Plane(new Point3d(bounds.Max.X+size*.5,bounds.Min.Y,bounds.Min.Z),Vector3d.XAxis,Vector3d.ZAxis);da.GetData(3,ref plane);if(!plane.IsValid)throw new ArgumentException("Legend Plane is invalid.");var legend=new List<GeometryBase>();
 for(int k=0;k<6;k++){double y=k*size*.35;var mesh=new Mesh();foreach(var pt in new[]{plane.PointAt(0,y),plane.PointAt(size*.2,y),plane.PointAt(size*.2,y+size*.35),plane.PointAt(0,y+size*.35)})mesh.Vertices.Add(pt);mesh.Faces.AddFace(0,1,2,3);mesh.VertexColors.CreateMonotoneMesh(Ramp(k/5d));legend.Add(mesh);var text=new TextEntity{Plane=new Plane(plane.PointAt(size*.28,y),plane.XAxis,plane.YAxis),TextHeight=size*.13,PlainText=(min+(max-min)*k/5).ToString("0.###",System.Globalization.CultureInfo.InvariantCulture)};legend.Add(text);}
 legend.Add(new TextEntity{Plane=new Plane(plane.PointAt(0,size*2.3),plane.XAxis,plane.YAxis),TextHeight=size*.14,PlainText="Solar irradiation [kWh/m²]\nSupplied analysis hours"});da.SetDataList(0,colored);da.SetDataList(1,legend);da.SetDataTree(2,PvDataTrees.Numbers(r.CellIrradiation));da.SetDataList(3,raw);da.SetDataList(4,r.Irradiation);da.SetDataList(5,r.Ids);var rows=new List<string>{"Panel ID,Area m2,Irradiation kWh/m2,Incident solar kWh,Irradiation reduction %"};for(int i=0;i<r.Ids.Length;i++)rows.Add("\""+r.Ids[i].Replace("\"","\"\"")+"\","+string.Join(",",new[]{r.AreaM2[i],r.Irradiation[i],r.AreaM2[i]*r.Irradiation[i],r.ShadingReductionPct[i]}.Select(x=>x.ToString("G17",System.Globalization.CultureInfo.InvariantCulture))));da.SetDataList(6,rows);da.SetData(7,$"{values.Length} analysis cells; legend {min:0.###}–{max:0.###} kWh/m². {r.Timestamps.Length} hourly records. Blue/red are scale-relative, not installation suitability. Cell map retains partial shading. Incident solar energy is not electrical energy.");Message=$"{values.Length} cells";
 }catch(Exception e){foreach(var p in Params.Output)p.ClearData();Message="";AddRuntimeMessage(GH_RuntimeMessageLevel.Error,e.Message);}}
}
}
